Translate("deDE", "badlands", {
	title = "Ödland",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Ödland ist ein Land aus rotem Fels, trockenen Rinnen und Wind. Südlich von {link:loch-modan}Loch Modan{/link} fallen die Berge zu Tafelbergen und Staubebenen ab, wo wenig wächst und noch weniger zu trinken findet. Felskojoten jagen über die Ebenen, Bussarde kreisen über den Schluchten, und lebender Stein wandelt dort, wo die Erde selbst im Zorn erwacht ist. Kein Königreich hält dieses Land. Und doch drängen sich hier die Ansprüche: {link:dwarves}Zwerge{/link} unter drei Bannern, {link:ogres}Oger{/link}, {link:troggs}Troggs{/link}, schwarze Drachen, ein Lager von Goblins, ein {link:gnomes}Gnom{/link} mit einem Experiment und eine Festung der {link:orcs}Orcs{/link} auf den westlichen Klippen. Die meisten von ihnen kamen wegen dessen, was unter den nördlichen Hügeln liegt. Dort ist das Gewölbe der Titanen, {link:uldaman}Uldaman{/link}, geöffnet worden, und jeder, der davon gehört hat, will, was es birgt.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Das Älteste im Ödland ist {link:uldaman}das Gewölbe von Uldaman{/link}, ein Werk der Titanen, älter als jede Zwergenhalle. Die {link:explorers-league}Forscherliga{/link} glaubt, dass seine Hallen die Antwort auf die Frage bergen, die die {link:dwarves}Zwerge{/link} am meisten beantworten wollen: woher ihr Volk stammt. Rund um das Gewölbe fand die Liga steinerne Urnen und verfallene Terrassen, gemeißelt von Händen, die keine Zwergenhände waren.

Die spätere Geschichte des Landes ist eine Geschichte des Krieges. Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} der {link:angor-fortress}Festung Angor{/link} hielten einst zwei Leutnants von {link:deathwing}Todesschwinge{/link} in der östlichen Klamm von {link:lethlor-ravine}Lethlor{/link} gefesselt, und im {link:second-war}Zweiten Krieg{/link} stand die {link:horde}Horde{/link} im Bund mit dem schwarzen Drachen, der ihr Herr war. Keine Chronik verzeichnet, wie das Land so unfruchtbar wurde oder wer es zuerst das Ödland nannte.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Jede Macht im Ödland liegt mit mindestens zwei anderen im Krieg. Der Shadowforge-Clan der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} hält die {link:angor-fortress}Festung Angor{/link} und gräbt in {link:uldaman}Uldaman{/link} nach Relikten der Titanen, und er untersteht einem Gesandten, den {red:ragnaros}Ragnaros{/red} selbst aus den Feuern des {link:blackrock-mountain}Blackrock{/link} geschickt hat. Sie sind bereits über die Grabung der Liga hergefallen, haben die meisten ihrer Arbeiter getötet und ihren Anführer verschleppt. Die {link:troggs}Troggs{/link} des Stonevault-Clans sind aus dem Gewölbe ausgeschwärmt und haben im Süden einen weiteren Prospektor der Liga getötet. Die Staubspeier-{link:ogres}Oger{/link} durchwühlen die Trümmer des zwergischen Rückzugs. Schwarze Drachen nisten in der Lethlorklamm, und das alte Siegel, das zwei ihrer Artgenossen bindet, gilt nicht mehr als sicher.

Die {link:horde}Horde{/link} hält {link:kargath}Kargath{/link} auf den westlichen Klippen. Von dort führt die Expeditionsstreitmacht von Kargath einen langen Krieg gegen den {link:blackrock-clan}Blackrockklan{/link} und die Dunkeleisenzwerge jenseits des Berges. Die {link:alliance}Allianz{/link} hat nur ein kleines Lager von Überlebenden der Liga südlich ihrer verlorenen Grabung, und diese warten auf Hilfe aus {link:ironforge}Ironforge{/link}.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:horde}Horde{/link} von {link:kargath}Kargath{/link}.{/b} {link:orcs}Orcs{/link}, {link:trolls}Trolle{/link}, {link:tauren}Tauren{/link} und {link:forsaken}Verlassene{/link}, die den westlichen Außenposten und die Straße zum {link:blackrock-mountain}Blackrock{/link} halten.
• {b}Die {link:explorers-league}Forscherliga{/link}.{/b} Eine Handvoll {link:dwarves}Zwerge{/link}, die den Fall von {link:hammertoe-s-digsite}Hammertoes Grabung{/link} überlebten.
• {b}Der Shadowforge-Clan.{/b} {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} der {link:angor-fortress}Festung Angor{/link}, ihre Golems und ihr dem Feuer verschworener Gesandter.
• {b}Die Stonevault-{link:troggs}Troggs{/link}.{/b} Sie halten die Zugänge zu {link:uldaman}Uldaman{/link} und die südlichen Grabungsstätten.
• {b}Die Staubspeier-{link:ogres}Oger{/link}.{/b} Sie haben Lager im ganzen Süden und Westen, und sie verkaufen ihre Keulen an jeden und verraten ihn dann.
• {b}Der schwarze Drachenschwarm.{/b} Welpen und versengte {link:the-night-watch}Wächter{/link} der schwarzen Drachen nisten in der Lethlorklamm.
• {b}Wanderer und Verbannte.{/b} Ein Goblinkoch, ein gejagter Schmied, ein gnomischer Magier und ein Wahnsinniger, der vor dem {link:twilight-s-hammer}Schattenhammer{/link} floh.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Schöpfer.{/b} {link:uldaman}Uldaman{/link} wurde von den Titanen in einem Zeitalter vor jedem sterblichen Königreich errichtet. Was es bewachen sollte, ist in der Halle der Forscher noch immer umstritten.
• {b}Die Bindung der Drachen.{/b} Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} der {link:angor-fortress}Festung Angor{/link} schufen einen Schlüssel, den sie das Zeichen der Erde nannten, und versiegelten damit zwei Leutnants von {link:deathwing}Todesschwinge{/link}, die Drachen {link:blacklash}Blacklash{/link} und {link:hematus}Hematus{/link}, unter der Lethlorklamm. Keine Chronik verzeichnet das Jahr.
• {b}Der Zweite Krieg.{/b} Die {link:horde}Horde{/link} kämpfte im {link:second-war}Zweiten Krieg{/link} an der Seite von Todesschwinge. Die {link:orcs}Orcs{/link} von {link:kargath}Kargath{/link} sehen dieses Bündnis heute als Makel auf ihrer Ehre.
• {b}Die Grabungen.{/b} In den letzten Jahren eröffnete die Liga Grabungen im ganzen Ödland unter Prospektor Agmond und dem Forscher Hammertoe Grez. Beide Grabungen sind nun gefallen.
• {b}Die Gegenwart.{/b} Die Shadowforge und die {link:troggs}Troggs{/link} graben im Gewölbe. Die Liga, die Horde und die {link:kirin-tor}Kirin Tor{/link} schicken alle ihre Leute, um sie aufzuhalten oder das Gesuchte als Erste zu finden.]=],
		},
		{
			title = "Überlieferungen des Ödlands",
			text = [=[• Die Überlebenden von {link:hammertoe-s-digsite}Hammertoes Grabung{/link} haben gelernt, dass die Wüste den Hungrigen Streiche spielt und dass nicht alles, was man über die Ebenen hinweg erblickt, wirklich dort ist.
• Der Schmied der Liga schwört, das Härteste im Ödland seien nicht die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}. Es sei, eine Mahlzeit zu finden.
• Im Magen eines großen Bussards fand ein Jäger einst eine narbige schwarze Kiste. Darauf waren die Worte „Maschine Nr. 19“ und der Name der Belagerungsbrigade von {link:ironforge}Ironforge{/link} gestempelt.
• Die {link:ogres}Oger{/link} des Ödlands tragen so viel Alteisen, dass der Schmied der Liga glaubt, die alten Geschichten von Belagerungsmaschinen in diesem Land seien wahr.
• Eine seltsame Maschine wandelt durch das südliche Ödland, ein Ding aus Zahnrädern, das niemandem gehorcht. Sie trägt den Titel einer Bergungseinheit für große Entfernungen, und niemand weiß, was sie bergen sollte.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik verzeichnet, wie das Ödland zur Wüste wurde, noch die Jahre, in denen {link:kargath}Kargath{/link} errichtet wurde und die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} die {link:angor-fortress}Festung Angor{/link} erbauten.]=],
		},
	},
})

Translate("deDE", "kargath", {
	title = "Kargath",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kargath ist die Festung der {link:horde}Horde{/link} im {link:badlands}Ödland{/link}, in die Klippen des Westrands gebaut. Sie trägt den Namen von Kargath Bladefist, einem Häuptling des Clans der Zerschmetterten Hand in den alten Kriegen. Windreiter landen auf ihren Höhen, Läufer tragen ihre Berichte nach Osten bis {link:stonard}Stonard{/link}, und ihr Gasthaus bietet Obdach für jene, die aus den brennenden Landen dahinter kommen. Kargath ist auch das Hauptquartier der Expeditionsstreitmacht von Kargath, des Heeres der Horde gegen den {link:blackrock-clan}Blackrockklan{/link} und die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} des {link:blackrock-mountain}Blackrock{/link}. Ihre Hauptleute schicken eine Kompanie nach der anderen in den Berg, und nicht alle kehren zurück.]=],
		},
	},
})

Translate("deDE", "angor-fortress", {
	title = "Festung Angor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Festung Angor ist eine Feste der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} im nördlichen {link:badlands}Ödland{/link}, einen kurzen Marsch von den Toren Uldamans entfernt. Vor langer Zeit schmiedeten ihre Erbauer dort das Zeichen der Erde, um zwei Drachen von {link:deathwing}Todesschwinge{/link} zu binden. Heute ist sie der Stützpunkt des Shadowforge-Clans. Seine Krieger, Gräber und Golems ziehen von ihren Toren in das Gewölbe, und von hier aus schlugen sie gegen {link:hammertoe-s-digsite}Hammertoes Grabung{/link} zu. Über ihnen allen steht {link:ambassador-infernus}Botschafter Infernus{/link}, von {red:ragnaros}Ragnaros{/red} gesandt, um die Suche nach Relikten der Titanen zu überwachen. {link:ironforge}Ironforge{/link} ist zu dem Schluss gekommen, dass die Arbeit der Shadowforge in {link:uldaman}Uldaman{/link} nur zu bremsen ist, wenn man Angor selbst angreift.]=],
		},
	},
})

Translate("deDE", "hammertoe-s-digsite", {
	title = "Hammertoes Grabungsstätte",
	aliases = { "Hammertoes Grabung" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hammertoes Grabungsstätte war das Lager der {link:explorers-league}Forscherliga{/link} im nördlichen {link:badlands}Ödland{/link}, geleitet vom Forscher Hammertoe Grez. Seine Gräber suchten im Boden um {link:uldaman}Uldaman{/link} nach Relikten der Titanen. Dann fiel der Shadowforge-Clan über das Lager her. Sie töteten fast jeden {link:dwarves}Zwerg{/link} dort und verschleppten Hammertoe lebend. Nur eine mit Kreide gekritzelte Karte verriet seinen Freunden, wohin er gebracht worden war. Einige Überlebende halten ein kleines Lager südlich der zerstörten Stätte, zwischen verlassenen Wagen und Kisten, und warten darauf, dass {link:ironforge}Ironforge{/link} Hilfe schickt.]=],
		},
	},
})

Translate("deDE", "agmond-s-end", {
	title = "Agmondkuppe",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Agmondkuppe ist ein Streifen zerklüfteten Bodens im Süden des Ödlands. Sie trägt ihren Namen nach Prospektor Agmond, der die Grabungen der Liga im {link:badlands}Ödland{/link} leitete, bis er verstummte. Man fand ihn hier, tot zwischen den Felsen. Er war einen langen Weg aus dem Westen gekrochen, blutend, und bevor er starb, ritzte er den Namen seines Mörders neben seiner Hand in den Sandstein: {link:murdaloc}Murdaloc{/link}. Die Stonevault-{link:troggs}Troggs{/link} jagen noch immer im Land um seine Gebeine.]=],
		},
	},
})

Translate("deDE", "lethlor-ravine", {
	title = "Die Lethlorklamm",
	aliases = { "Lethlor" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Lethlorklamm ist eine große Narbe im östlichen {link:badlands}Ödland{/link}, und sie gehört den schwarzen Drachen. Ihre Welpen und versengten {link:the-night-watch}Wächter{/link} nisten auf ihrem Grund. Unter ihr liegen die Drachen {link:blacklash}Blacklash{/link} und {link:hematus}Hematus{/link}, Leutnants von {link:deathwing}Todesschwinge{/link}, gefangen in einem Kerker, den die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} der {link:angor-fortress}Festung Angor{/link} schufen. Drei Runensteine halten das Siegel, jeder in eine Säule aus Amethyst, Opal oder Diamant gesetzt, und nur das Zeichen der Erde kann sie herausziehen. Die {link:horde}Horde{/link} wie die {link:kirin-tor}Kirin Tor{/link} fürchten nun, dass das Siegel nicht für immer halten wird.]=],
		},
	},
})

Translate("deDE", "dustbelch-grotto", {
	title = "Die Staubspeiergrotte",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Staubspeiergrotte ist das Hauptlager der Staubspeier-{link:ogres}Oger{/link} im südwestlichen {link:badlands}Ödland{/link}. Um sie herum liegen die kleineren Lager Cagg und Wurg. Die Oger dort sind für ihre Art gut bewaffnet, denn sie haben das Alteisen von jedem Wrack und jedem Wagen abgerissen, den die Wüste ihnen überlassen hat. Ihre Schamanen und Ogermagier haben ihre eigenen Beziehungen zu den Felselementaren, die in der Nähe wandeln. Die {link:horde}Horde{/link} zählte solche Oger einst zu den Ihren. In {link:kargath}Kargath{/link} erinnern sich heute nur wenige daran als an etwas anderes als einen Fehler.]=],
		},
	},
})

Translate("deDE", "camp-boff", {
	title = "Camp Boff",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Camp Boff ist ein Ogerlager im Süden des Ödlands. Es ist eine der Stationen einer umherziehenden Bande von Staubspeier-Söldnern unter {link:boss-tho-grun}Boss Tho'grun{/link}. Die {link:horde}Horde{/link} von {link:kargath}Kargath{/link} heuerte Tho'grun an, um ihr zu helfen, das Zeichen der Erde zu nehmen. Er nahm es, wandte sich dann gegen seine Auftraggeber und behielt es. Seitdem zieht die Bande von Lager zu Lager durch das {link:badlands}Ödland{/link}, und ihre Spur ist in Hitze und Wind schwer zu verfolgen.]=],
		},
	},
})

Translate("deDE", "camp-kosh", {
	title = "Camp Kosh",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Camp Kosh ist ein Ogerlager im Nordosten des Ödlands, nicht weit von der Straße, die die {link:dwarves}Zwerge{/link} auf ihrer Flucht von der Grabung bei {link:uldaman}Uldaman{/link} nahmen. Die Staubspeier von Kosh fielen über die Wagen und Kisten her, die die Zwerge zurückließen. Unter ihrer Beute war der Karren, der die Waffen und die Nahrung der Überlebenden trug, und das Lager der Liga hungerte, bis er zurückgeholt wurde.]=],
		},
	},
})

Translate("deDE", "the-dustbowl", {
	title = "Die Staubschüssel",
	aliases = { "Staubschüssel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Staubschüssel ist ein weites, trockenes Becken im Westen des Ödlands, einen Tagesmarsch östlich von {link:kargath}Kargath{/link}. Ihr offener Boden und ihre Felselementare haben den gnomischen Magier {link:lotwil-veriatus}Lotwil Veriatus{/link} angelockt, der hier mit seinem Gehilfen und seinem mechanischen Diener sein Lager aufgeschlagen hat. Die Felselementare sind sein Rohstoff. Lotwil nennt den Ort vollkommen. Wer gesehen hat, was bei seinem letzten Experiment herauskam, ist sich weniger sicher.]=],
		},
	},
})

Translate("deDE", "valley-of-fangs", {
	title = "Fangzahntal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Fangzahntal liegt im Herzen des Ödlands. Felskojoten und Gratpirscher jagen an seinen Hängen, und Bussarde warten auf das, was sie übrig lassen. In seiner Mitte hält ein kleines Lager seine Feuer am Brennen: ein Goblinkoch namens {link:rigglefuzz}Rigglefuzz{/link}, ein Goblin, der Schmiedebedarf verkauft, und der Schmied {link:martek-the-exiled}Martek{/link}, der hierherkam, um in Ruhe gelassen zu werden. Rigglefuzz verscheucht die Tiere mit Blitzbomben aus eigener Herstellung.]=],
		},
	},
})

Translate("deDE", "mirage-flats", {
	title = "Illusionenebene",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Illusionenebene erstreckt sich über das südwestliche {link:badlands}Ödland{/link}, und ihr Name ist eine Warnung. Hitze steigt in Wellen von der trockenen Erde auf, und die wirbelnden Winde tragen Staub über die Ebene, bis man nichts mehr trauen kann, was man in der Ferne sieht. In letzter Zeit sprechen manche von einem Trugbild in der Ebene, das mehr ist als ein Spiel des Lichts und das nicht vergeht, wenn man sich ihm nähert.]=],
		},
	},
})

Translate("deDE", "apocryphan-s-rest", {
	title = "Apocryphans Ruheplatz",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Apocryphans Ruheplatz ist ein Streifen des westlichen Ödlands zwischen {link:kargath}Kargath{/link} und den Ogerlagern des Südens. Felselementare wandern über seine Steine, und die geringeren sind hier leicht zu finden für jene, die ihre Splitter wollen. Keine Aufzeichnung Kargaths oder der Liga erklärt den Namen oder wer der Apocryphan war, falls es ihn je gab.]=],
		},
	},
})

Translate("deDE", "dustwind-gulch", {
	title = "Staubwindschlucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Staubwindschlucht ist ein Canyon im östlichen {link:badlands}Ödland{/link}, an der Straße zwischen dem Lager der Liga und den schwarzen Drachen der Lethlorklamm. Es ist ein einsamer Ort, und so passt er zu einem einsamen Auftrag. Nahe seinem Südende hält der Magier {link:garek}Garek{/link} still Wache für seinen Meister bei den {link:kirin-tor}Kirin Tor{/link}, den Kerker der Drachen im Rücken.]=],
		},
	},
})

Translate("deDE", "the-maker-s-terrace", {
	title = "Terrasse des Schöpfers",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Terrasse des Schöpfers ist die Anhöhe vor den Toren von {link:uldaman}Uldaman{/link} im nördlichen {link:badlands}Ödland{/link}. Der Name erinnert an die Titanen, die Schöpfer, die das Gewölbe errichteten. Die {link:dwarves}Zwerge{/link} der Liga kamen hierher, um ihre Grabungen zu eröffnen, und die Shadowforge und die {link:troggs}Troggs{/link} folgten ihnen. Gemeißelte Steinurnen liegen verstreut um die alten Ausgrabungen. {link:prospector-ironband}Prospektor Ironband{/link} glaubt, dass sie die Troggs in Raserei versetzten.]=],
		},
	},
})

Translate("deDE", "theldurin-the-lost", {
	title = "Theldurin der Verlorene",
	subtitle = "Flüchtling des Schattenhammers",
	found = "Zwischen den Felsen des südlichen Ödlands",
	hint = [=[Sucht den Wahnsinnigen, der sich zwischen den Felsen des südlichen Ödlands versteckt.]=],
	allegiance = "Einst der Schattenhammer",
	aliases = { "Theldurin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Theldurin der Verlorene ist ein {link:dwarves}Zwerg{/link}, der einst dem {link:twilight-s-hammer}Schattenhammer{/link} angehörte. Etwas, das er in diesem Orden erfuhr, zerbrach seinen Geist, und er wandte sich gegen ihn. Als er floh, nahm er die Schriftrolle von {link:myzrael}Myzrael{/link} mit, dem Wesen, das die Riesen unter dem {link:arathi-highlands}Arathihochland{/link} banden. Nun versteckt er sich im {link:badlands}Ödland{/link}. Er redet mit sich selbst, lacht über nichts und entschuldigt sich dafür, dann nimmt er die Entschuldigung zurück. Unter dem Wahnsinn hat er schreckliche Angst, und er hat Grund dazu.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Theldurin ist der Beweis, dass der {link:twilight-s-hammer}Schattenhammer{/link} Mächten dient, die gewöhnliche Geister nicht ertragen können. Er weiß, worauf sein alter Orden wartet, und er hat es zu seiner Aufgabe gemacht, es zu verhindern. Seine Furcht gilt nicht {link:myzrael}Myzrael{/link} allein. Er spricht von anderen, weit älteren, deren Namen er nicht laut aussprechen will, für den Fall, dass sie ihn hören.]=],
		},
		{
			title = "Taten",
			text = [=[• Er stahl die Schriftrolle von {link:myzrael}Myzrael{/link} aus dem {link:twilight-s-hammer}Schattenhammer{/link}.
• Er flickte die Schriftrolle, nachdem wütende Elementare sie zerrissen hatten.
• Er suchte die Tafel von Ryun'eh in {link:uldaman}Uldaman{/link} und das Kompendium eines alten Schreibers namens Yagyin.
• Er gab sich als einer seines alten Ordens aus, indem er ihr Zeichen, das Siegel des Hammers, vorzeigen ließ.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Aufzeichnung nennt Theldurins Clan, seine Jahre im {link:twilight-s-hammer}Schattenhammer{/link} oder was er sah, das seinen Geist zerbrach.]=],
		},
	},
	chapters = {
		{
			title = "Die zerrissene Schriftrolle",
			hint = "Holt die Bruchstücke der Schriftrolle von Myzrael zurück.",
			text = [=[Die Diener des Hammers kamen und suchten nach der Schriftrolle. Theldurin hatte sie nicht. Wütende Elementare hatten sie ihm entrissen und kämpften nun untereinander um die Stücke. Als die Bruchstücke zurückgebracht wurden, machte er sich mit einer Schrottratsche an die Arbeit und setzte die Schriftrolle zusammen. Er hoffte, dass es nicht schon zu spät war.]=],
		},
		{
			title = "Die Fesseln der Prinzessin",
			hint = [=[Erfahrt von dem Wahnsinnigen, wie Myzrael wieder gebunden werden kann.]=],
			text = [=[{link:myzrael}Myzrael{/link} sei frei, sagte Theldurin, und sammle Kraft. Sie müsse herbeigerufen und besiegt werden, bevor sie stark genug sei, um gegen ihre Kerkermeister zuzuschlagen. Manche in seinem alten Orden glaubten, sie beherrschen zu können. Er stellte die naheliegende Frage: Wenn man sie beherrschen könnte, warum hätten die Riesen sie dann in Ketten gelegt?]=],
		},
		{
			title = "Die Tafel von Ryun'eh",
			hint = [=[Bringt dem Wahnsinnigen die Tafel, die tief in Uldaman liegt.]=],
			text = [=[Ein Verhängnis komme, sagte Theldurin, und er konnte es nicht ertragen, jene zu nennen, die es bringen würden. Er schickte einen Sucher nach {link:uldaman}Uldaman{/link}, um eine Tafel zu holen, die in einer Truhe verborgen war, älter als jedes Zwergenwerk. Als sie zurückkam, jubelte er. Dann las er sie, und sie genügte nicht.]=],
		},
		{
			title = "Yagyins Kompendium",
			hint = [=[Bringt dem Wahnsinnigen das Kompendium, das sein alter Orden verwahrt.]=],
			text = [=[Das Kompendium von Yagyin wurde vom {link:twilight-s-hammer}Schattenhammer{/link} an vielen Orten verwahrt, und seine gelehrten Mitglieder studierten es. Theldurin gab seinem Sucher das Siegel des Hammers und schickte ihn zu den Verwahrern seines alten Ordens in {link:ironforge}Ironforge{/link} und {link:undercity}Undercity{/link}. Das Kompendium kam endlich zu ihm zurück. Er weinte vor Hoffnung und Lobpreis. Dann warnte er im selben Atemzug, dass niemand am Leben bliebe, um Enkel zu haben, sollten die Verborgenen je auferstehen.]=],
		},
	},
	mentions = {
		{ text = "Theldurin der Verlorene" },
		{ text = "Die verlorenen Bruchstücke" },
		{ text = "Die Beschwörung der Prinzessin" },
		{ text = "Lösung für das Verhängnis" },
		{ text = "Nach {link:ironforge}Ironforge{/link} für Yagyins Kompendium" },
		{ text = "Nach {link:undercity}Undercity{/link} für Yagyins Kompendium" },
		{ text = "Der Stern, die Hand und das Herz" },
		{ text = "Verbotenes Wissen" },
	},
	bonds = {
		{ id = "myzrael", name = "Myzrael", note = "das Wesen, dessen Schriftrolle er stahl" },
		{ id = "zaruk", name = "Zaruk", note = "von seinem alten Orden, in Hammerfall" },
		{ id = "gerrig-bonegrip", name = "Gerrig Bonegrip", note = "verwahrt das Kompendium in Ironforge" },
		{ id = "keeper-bel-dugur", name = "Bewahrer Bel'dugur", note = "verwahrt das Kompendium in Undercity" },
	},
})

Translate("deDE", "prospector-ryedol", {
	title = "Prospektor Ryedol",
	subtitle = "Prospektor der Forscherliga",
	found = "Das Lager der Liga südlich von Hammertoes Grabungsstätte",
	hint = [=[Findet den Prospektor, der den Fall von Hammertoes Grabung überlebte.]=],
	allegiance = "Forscherliga",
	aliases = { "Ryedol" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Prospektor Ryedol arbeitete unter dem Forscher Hammertoe Grez an dessen Grabung im nördlichen {link:badlands}Ödland{/link}. Als der Shadowforge-Clan angriff, war er einer der wenigen, die entkamen. Nun hält er mit {link:sigrun-ironhew}Sigrun Ironhew{/link} und den anderen Überlebenden ein kleines Lager südlich der zerstörten Stätte. Er spricht geradeheraus und ist müde, und er sagt, dass jeder Tag im Ödland ein schlechter ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ryedol ist der Faden, der Hammertoes Schicksal mit {link:ironforge}Ironforge{/link} verbindet. Durch ihn erfuhr das Königreich, dass die Shadowforge nicht einfach plünderten. Sie jagten nach den Geheimnissen der Titanen und nach dem Wissen, das Hammertoe im Kopf trug.]=],
		},
		{
			title = "Taten",
			text = [=[• Er entkam dem Angriff der Shadowforge auf {link:hammertoe-s-digsite}Hammertoes Grabung{/link}.
• Er erfuhr aus einer gekritzelten Karte, dass Hammertoe lebend nach {link:uldaman}Uldaman{/link} gebracht worden war.
• Er schickte einen Sucher in das Gewölbe, um seinen alten Meister zu finden.
• Er ließ Hammertoes Amulett durch die Hand eines anderen zu {link:historian-karnik}Historiker Karnik{/link} nach {link:ironforge}Ironforge{/link} bringen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Nichts ist über Ryedols Leben vor dem {link:badlands}Ödland{/link} geschrieben.]=],
		},
	},
	chapters = {
		{
			title = "Die Glückshacke",
			hint = "Holt die Hacke des Prospektors von den Shadowforge zurück.",
			text = [=[Ryedol verlor bei dem Angriff alles, sogar seine Glückshacke. Er glaubte, einer der Shadowforge habe sie genommen. Als sie zu ihm zurückkam, war er dankbar. Er war auch beunruhigt. Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} hätten die Grabung nicht zufällig angegriffen, sagte er. Sie suchten nach etwas.]=],
		},
		{
			title = "Ein Zeichen der Hoffnung",
			hint = [=[Berichtet dem Prospektor, was die mit Kreide bekritzelte Karte verrät.]=],
			text = [=[Nahe der zerstörten Grabung wurde eine Karte gefunden, auf die mit Kreide eine Botschaft gekritzelt war: Hammertoe werde nach {link:uldaman}Uldaman{/link} gebracht. Ryedol hatte ihn als tot betrauert. Nun verstand er, warum die Shadowforge ihn verschont hatten. Sie wollten, was Hammertoe über die Ausgrabungen der Titanen wusste. Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} suchten seit langem nach Wegen, stärkere Golems zu bauen. Hammertoe hatte dieselben Geheimnisse studiert, um sie aufzuhalten.]=],
		},
		{
			title = "Aussicht auf Glauben",
			hint = "Bringt dem Prospektor, was Hammertoe zurückließ.",
			text = [=[Hammertoe wurde in {link:uldaman}Uldaman{/link} gefunden, doch er lag im Sterben. Er schickte sein Amulett zurück, das Werk seines Lebens, und bat, dass es an Ryedol gehe. Ryedol sagte, er sei glücklicher gewesen, als er seinen Meister schon für tot hielt. Dann fasste er sich. Hammertoe hatte mit {link:historian-karnik}Historiker Karnik{/link} von {link:ironforge}Ironforge{/link} zusammengearbeitet, und Karnik würde wissen, was das Amulett bedeutete. Ryedol schickte es an ihn weiter, damit der Tod nicht vergebens sei.]=],
		},
	},
	mentions = {
		{ text = "Ein {link:dwarves}Zwerg{/link} und sein Werkzeug" },
		{ text = "Ein Zeichen der Hoffnung" },
		{
			text = [=[Ein Zeichen der Hoffnung, nach {link:uldaman}Uldaman{/link} gesandt]=],
		},
		{ text = "Aussicht auf Glauben, Hammertoes Amulett zurückgebracht" },
		{
			text = [=[Aussicht auf Glauben, nach {link:ironforge}Ironforge{/link} weitergetragen]=],
		},
	},
	bonds = {
		{ id = "hammertoe-grez", name = "Hammertoe Grez", note = "sein Meister" },
		{ id = "sigrun-ironhew", name = "Sigrun Ironhew", note = "teilt sein Lager" },
		{ id = "historian-karnik", name = "Historiker Karnik", note = "Hammertoes Partner in Ironforge" },
	},
})

Translate("deDE", "sigrun-ironhew", {
	title = "Sigrun Ironhew",
	subtitle = "Schmied des Lagers der Liga",
	found = "Das Lager der Liga südlich von Hammertoes Grabungsstätte",
	hint = [=[Sprecht mit dem Schmied des kleinen Lagers der Liga im nördlichen Ödland.]=],
	allegiance = "Forscherliga",
	aliases = { "Sigrun" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sigrun Ironhew ist der Schmied des Lagers der Liga. Er floh mit den anderen Überlebenden von der Grabung bei {link:uldaman}Uldaman{/link}, und nun versucht er, aus nichts ein Lager zu machen. Die {link:ogres}Oger{/link} haben ihren Vorratskarren genommen, es gibt kein Alteisen für Befestigungen, und es gibt kein Essen. Sigrun behält seinen Humor, auch wenn er dünn wird.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Sigrun erlernte sein Handwerk als Lehrling des Schmieds Feranor Steeltoe, von dem er eine geheime Weise übernahm, mit dem Blut aus dem Herzen eines schwarzen Drachen Feuer in Stahl zu binden.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bittet um den Vorratskarren, den die {link:ogres}Oger{/link} von {link:camp-kosh}Camp Kosh{/link} fortschafften.
• Er sammelt Alteisen von den Ogern, um die Befestigungen des Lagers zu bauen.
• Er verzaubert Waffen mit Feuer, mit den Herzen von Drachenwelpen aus der Lethlorklamm.]=],
		},
	},
	mentions = {
		{ text = "Trugbilder" },
		{ text = "Plünderung" },
		{ text = "Verzauberungen mit feuriger Glut" },
	},
	bonds = {
		{ id = "prospector-ryedol", name = "Prospektor Ryedol", note = "teilt sein Lager" },
		{ id = "garek", name = "Garek", note = "hörte von seinen Helfern" },
	},
})

Translate("deDE", "garek", {
	title = "Garek",
	subtitle = "Agent der Kirin Tor",
	found = "Staubwindschlucht, westlich der Lethlorklamm",
	hint = "Findet den stillen Magier, der über die Lethlorklamm wacht.",
	allegiance = "Kirin Tor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[{link:garek-bandarion}Garek{/link} ist ein Magier, der von einem Meister bei den {link:kirin-tor}Kirin Tor{/link}, Krasus, ins {link:badlands}Ödland{/link} gesandt wurde. Der Magier hält ein einsames Lager nahe der Lethlorklamm und sagt wenig über seinen Auftrag, nur dass er von großer Bedeutung sei und die Unruhe betreffe, die sich in der Klamm zusammenbraut.]=],
		},
		{
			title = "Bedeutung",
			text = [=[{link:garek-bandarion}Garek{/link} zeigt, dass die {link:kirin-tor}Kirin Tor{/link} den schwarzen Drachenschwarm noch immer beobachten, selbst in diesen unruhigen Jahren. Unter der Lethlorklamm liegen zwei Leutnants von {link:deathwing}Todesschwinge{/link}, und sein Meister hat entschieden, dass keinerlei Gefahr ihrer Befreiung hingenommen werden darf.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sucht das Zeichen der Erde, den Schlüssel zum Kerker der Drachen, das von einer umherziehenden Ogerbande gestohlen wurde.
• Er erfuhr die Geschichte des Kerkers und seiner Erbauer, der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}.
• Er ist entschlossen, dass {link:blacklash}Blacklash{/link} und {link:hematus}Hematus{/link} nicht wieder erwachen dürfen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[{link:garek-bandarion}Garek{/link} sagt nicht, wer er war, bevor er in den Dienst seines Meisters trat, und keine Aufzeichnung verrät es.]=],
		},
	},
	chapters = {
		{
			title = "Das Zeichen der Erde",
			hint = [=[Holt den gestohlenen Schlüssel für den Magier der Kirin Tor zurück.]=],
			text = [=[Das Zeichen der Erde wurde von den Dunkeleisenzwergen der {link:angor-fortress}Festung Angor{/link} geschaffen, um zwei Leutnants von {link:deathwing}Todesschwinge{/link} zu binden, die Zwillingsdrachen {link:blacklash}Blacklash{/link} und {link:hematus}Hematus{/link}. Als man es ihm brachte, sprach {link:garek-bandarion}Garek{/link} offener. Die schwarzen Drachen waren gekommen, um in der Klamm zu nisten. Den Ogern war es gelungen, das Zeichen zu stehlen. Dem Kerker war nicht mehr zu trauen.]=],
		},
		{
			title = "Ewige Träume",
			hint = "Beendet die Gefahr durch die Drachen von Lethlor.",
			text = [=[Mit dem Zeichen konnten die drei Runensteine aus ihren Säulen gezogen und in das Siegel der Erde gesetzt werden. Das Siegel brach, und die Drachen waren frei, so lange, wie es dauerte, sie zu erschlagen. {link:garek-bandarion}Garek{/link} bat nur darum, dass ihre Träume ewig würden. Als es vollbracht war, bereitete er sich darauf vor, zu Krasus zurückzukehren mit der Nachricht, dass die {link:kirin-tor}Kirin Tor{/link} die Gefangenen von {link:lethlor-ravine}Lethlor{/link} nicht mehr fürchten müssten.]=],
		},
	},
	mentions = {
		{ text = "Beben der Erde, das Zeichen zurückgeholt" },
		{ text = "Beben der Erde, die Drachen erschlagen" },
		{ text = "Siegel der Erde" },
	},
	bonds = {
		{ id = "sigrun-ironhew", name = "Sigrun Ironhew", note = "erzählte ihm von jenen, die helfen" },
		{ id = "blacklash", name = "Blacklash", note = "ein Gefangener von Lethlor" },
		{ id = "hematus", name = "Hematus", note = "ein Gefangener von Lethlor" },
		{ id = "boss-tho-grun", name = "Boss Tho'grun", note = "stahl das Zeichen" },
	},
})

Translate("deDE", "blacklash", {
	title = "Blacklash",
	subtitle = "Leutnant von Todesschwinge",
	found = "Gebunden unter dem Siegel der Erde, Lethlorklamm",
