Translate("deDE", "lotwil-veriatus", {
	title = "Lotwil Veriatus",
	subtitle = "Magier und Tüftler aus Kharanos",
	found = "Sein Lager in der Staubschüssel",
	hint = [=[Findet den gnomischen Magier, der seine Erfindungen in der Staubschüssel erprobt.]=],
	allegiance = "Gnome · Kharanos",
	aliases = { "Lotwil" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lotwil Veriatus ist ein {link:gnomes}Gnom{/link}, der Alchemie, Ingenieurskunst und arkane Magie im Dienst seiner eigenen Neugier verbindet. Er ist aus {link:kharanos}Kharanos{/link} ins {link:badlands}Ödland{/link} gekommen, um sein größtes Werk zu bauen: Fesseln der Elementarbindung, mit denen ein Magier Elementare befehligen könnte, weit stärker als alle, die je zuvor gerufen wurden. Sein Gehilfe {link:lucien-tosselwrench}Lucien{/link} und sein ungeschickter mechanischer Diener Servo teilen sein Lager. Lotwil ist brillant, zerstreut und fröhlich davon überzeugt, dass jeder Rückschlag ein kleiner ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Lotwil ist ein Gelehrter von echtem Ruf in den Elementarwissenschaften, und selbst die {link:horde}Horde{/link} von {link:kargath}Kargath{/link} sucht sein Urteil. Er hat auch eine Vergangenheit. Vor langer Zeit kämpfte er gegen einen Dunkeleisenzwerg, der sein Lebenswerk zu Waffen verdrehte, und er glaubte diesen Feind tot.]=],
		},
		{
			title = "Taten",
			text = [=[• Er studiert die Felselementare des Ödlands, um seine Fesseln zu bauen.
• Er kühlt und stärkt seine Fesseln mit Frostöl und einer Vorrichtung namens Gyrochronatom.
• Er beschwört mit seinen fertigen Fesseln einen {link:the-night-watch}Wächter{/link} aus Stein, was nicht so verläuft, wie er es plante.
• Er kennt die Zeichen des Golemschöpfers Argelmach.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Die Chroniken erzählen nicht, wie Lotwil und Argelmach sich zuerst begegneten oder wie der Dunkeleisenzwerg an das Werk des Gnoms kam.]=],
		},
	},
	chapters = {
		{
			title = "Studium der Elemente",
			hint = [=[Sammelt, was der Gnom von den Felselementaren des Ödlands braucht.]=],
			text = [=[Splitter von den geringeren Elementaren, Platten von den größeren und zuletzt die Armschienen der Felsbindung vom größten von ihnen. Jedes Stück ließ Lotwil seine Zauber am Stoff lebendigen Felsens erproben. Jede Probe verlief, wie er es vorhergesagt hatte. Er begann von den Elementaren zu sprechen, die er bald beherrschen würde, und wie sie alle früheren Beschwörungen in den Schatten stellen würden.]=],
		},
		{
			title = "Das wird schwierig",
			hint = [=[Helft dem Gnom, seine Fesseln zu vollenden, und kümmert Euch um das, was folgt.]=],
			text = [=[Die Fesseln waren fertig. Lotwil rief {link:lucien-tosselwrench}Lucien{/link} und Servo als Zeugen herbei und beschwor einen {link:the-night-watch}Wächter{/link} aus elementarem Stein. Er gehorchte nicht. Als das Geschöpf besiegt und seine Fesseln zurückgeholt waren, gab Lotwil zu, dass dies nicht der Ausgang gewesen sei, den er erwartet hatte. Er konnte nicht sagen, was schiefgegangen war. Er sei froh, sagte er, dass seine Magie da gewesen sei, um das Geschöpf nach Hause zu schicken.]=],
		},
		{
			title = "Der Aufstieg der Maschinen",
			hint = [=[Bringt den gezeichneten Elementarsplitter von Kargath zum Lager des Gnoms.]=],
			text = [=[Die Splitter stammten von Golems in der {link:burning-steppes}Brennenden Steppe{/link}, und sie trugen Initialen. Als Lotwil sie sah, wurde er kreidebleich. Er kannte die Zeichen. Sie gehörten Argelmach, einem Dunkeleisenzwerg, der Lotwils eigenes Werk zu bösen Zwecken verbogen hatte und den Lotwil Jahre zuvor mit eigener Hand getötet hatte. Als Argelmachs Kopf aus den {red:blackrock-depths}Blackrocktiefen{/red} gebracht wurde, war er nicht aus Fleisch. Er war eine Maschine, nach Argelmachs Bild gemacht, und Lotwil fürchtete, dass eine weitere erstehen würde, um ihren Platz einzunehmen.]=],
		},
	},
	mentions = {
		{ text = "Studium der {link:elements}Elemente{/link}: Fels" },
		{ text = "Studium der {link:elements}Elemente{/link}: Fels" },
		{ text = "Studium der {link:elements}Elemente{/link}: Fels" },
		{ text = "Kühle Köpfe siegen" },
		{ text = "Gyro... was?" },
		{ text = "Das wird schwierig" },
		{ text = "Das wird schwierig, das Zahnrad übergeben" },
		{
			text = [=[Das wird schwierig, der {link:the-night-watch}Wächter{/link} entfesselt]=],
		},
		{
			text = [=[Der Aufstieg der Maschinen, der Splitter aus {link:kargath}Kargath{/link} gebracht]=],
		},
		{ text = "Der Aufstieg der Maschinen, Argelmachs Kopf" },
	},
	bonds = {
		{ id = "lucien-tosselwrench", name = "Lucien Tosselwrench", note = "sein Gehilfe" },
		{ id = "hierophant-theodora-mulvadania", name = "Hierophantin Theodora Mulvadania", note = "sucht sein Urteil" },
		{ id = "golem-lord-argelmach", name = "Golemlord Argelmach", note = "sein alter Feind" },
	},
})

Translate("deDE", "lucien-tosselwrench", {
	title = "Lucien Tosselwrench",
	subtitle = "Gehilfe von Lotwil Veriatus",
	found = "Lotwils Lager in der Staubschüssel",
	hint = [=[Sprecht mit dem Gehilfen, der vorsichtig Abstand zu Lotwils Arbeit hält.]=],
	allegiance = "Kharanos",
	aliases = { "Lucien" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lucien Tosselwrench ist der Gehilfe von {link:lotwil-veriatus}Lotwil Veriatus{/link}, und er hat von seinem Meister mehr gelernt, als Lotwil ahnt. Aus Lotwils Forschungen im {link:badlands}Ödland{/link} hat er ein eigenes Trankrezept entwickelt, und er verzaubert Armschienen mit dem übrigen Stein, den Lotwil sammelt. Er kennt seinen Meister auch gut genug, um vor jedem Experiment in Deckung zu gehen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Lucien ist die praktische Hälfte von Lotwils Lager. Wo {link:lotwil-veriatus}Lotwil{/link} Triumph vor sich sieht, sieht Lucien Ärger, und er bereitet sich darauf vor.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sammelt Heil- und Unsichtbarkeitstränke für den Fall, dass Lotwils Arbeit schiefgeht.
• Er fertigt verzauberte Armschienen aus dem übrigen Stein der Elementare.
• Er übergibt Zahnrad Nummer fünf und tritt dann in Deckung.]=],
