})

Translate("deDE", "rigglefuzz", {
	title = "Rigglefuzz",
	subtitle = "Goblinkoch des Ödlands",
	found = "Das Lager im Fangzahntal",
	hint = "Findet den Goblin, der mitten im Ödland Bussardflügel brät.",
	allegiance = "Goblins",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rigglefuzz ist ein Goblin, der im Herzen des Ödlands lebt, wo er durch List überlebt. Er hält die Tiere mit Blitzbomben fern, und er ist stolz auf seine gegrillten Bussardflügel, deren Duft, wie er behauptet, Hungrige meilenweit anlocken kann. Er hegt auch einen Groll. Die Shadowforge verschleppten ihn einst in die {link:angor-fortress}Festung Angor{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Rigglefuzz ist derjenige, der die Shadowforge das Geheimnis der seltsamen Steine von {link:uldaman}Uldaman{/link} lehrte. Sie brachten ihn in die {link:angor-fortress}Festung Angor{/link}, um zwei Arten von Stein aus dem Gewölbe zu untersuchen, und er fand heraus, dass sie, richtig behandelt, beständige und dauerhafte Kraftquellen waren. Als er es ihnen sagte, warfen sie ihn hinaus und begannen, nach mehr zu graben.]=],
		},
		{
			title = "Taten",
			text = [=[• Er stellt Blitzbomben aus zerstoßenen blauen Perlen her, die von den Riffen des {link:stranglethorn-vale}Schlingendorntals{/link} gebracht werden.
• Er brät Bussardflügel und teilt das Rezept mit denen, die ihm helfen.
• Er will die Kraftsteine von {link:uldaman}Uldaman{/link} für seine eigenen Vorrichtungen.]=],
		},
	},
	mentions = {
		{ text = "Gegrillte Bussardflügel" },
		{ text = "Perlentauchen" },
		{ text = "Rezept für Blitzbomben" },
		{ text = "Kraftsteine" },
	},
	bonds = {
		{ id = "martek-the-exiled", name = "Martek der Verbannte", note = "teilt sein Lager" },
	},
})

Translate("deDE", "martek-the-exiled", {
	title = "Martek der Verbannte",
	subtitle = "Verbannter Schmied",
	found = "Das Lager im Fangzahntal",
	hint = [=[Findet den Schmied, der ins Ödland gekommen ist, um in Ruhe gelassen zu werden.]=],
	allegiance = "Keine",
	aliases = { "Martek" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Martek ist ein Schmied von großem Geschick, der mehr über Metall weiß als fast jeder andere. Er ist auch ein gejagter Mann. Viele hätten ihn gern tot, und er erwartet, dass jeder Fremde einer von ihnen ist. Er fragt Besucher, ob sie wegen der Axt gekommen seien, die er für {link:gath-ilzogg}Gath'Ilzogg{/link} schmiedete, oder um die Ehre einer Herzogin Pamay zu rächen, und sagt, es sei ihm gleich, was davon.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Martek fand im {link:badlands}Ödland{/link} ein Metall namens Indurium, das Hitze und Belastung widersteht wie kein anderes. Das wahre Erz liegt tief in {link:uldaman}Uldaman{/link}. Durch ihn erreichte die Kunde davon den {link:gnomes}Gnom{/link} {link:fizzle-brassbolts}Fizzle Brassbolts{/link} in {link:thousand-needles}Tausend Nadeln{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schmiedete eine Axt für den {link:ogres}Oger{/link} {link:gath-ilzogg}Gath'Ilzogg{/link}.
• Er prüft die Induriumflocken, die die Stonevault-{link:troggs}Troggs{/link} bei sich tragen.
• Er lässt {link:fizzle-brassbolts}Fizzle Brassbolts{/link} wissen, dass sich aus Indurium Kolben für seinen Rennwagen machen lassen.]=],
		},
	},
	mentions = {
		{ text = "Martek der Verbannte" },
		{ text = "Indurium" },
		{ text = "Neuigkeiten für Fizzle" },
	},
	bonds = {
		{ id = "fizzle-brassbolts", name = "Fizzle Brassbolts", note = "einer der wenigen, die ihm Gutes wünschen" },
		{ id = "rigglefuzz", name = "Rigglefuzz", note = "teilt sein Lager" },
		{ id = "gath-ilzogg", name = "Gath'Ilzogg", note = "kaufte seine Axt" },
	},
})

Translate("deDE", "warlord-goretooth", {
	title = "Kriegsherr Goretooth",
	subtitle = "Befehlshaber der Expeditionsstreitmacht von Kargath",
	found = "Kargath",
	hint = [=[Sprecht mit dem Kriegsherrn, der das Heer der Horde in Kargath befehligt.]=],
	allegiance = "Horde · Expeditionsstreitmacht von Kargath",
	aliases = { "Goretooth" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kriegsherr Goretooth befehligt die Expeditionsstreitmacht von {link:kargath}Kargath{/link}, das Heer, das die {link:horde}Horde{/link} im {link:badlands}Ödland{/link} unterhält, um gegen den {link:blackrock-clan}Blackrockklan{/link} und die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} des {link:blackrock-mountain}Blackrock{/link} zu kämpfen. Er ist ein harter Soldat, zu beschäftigt für Besucher und zu stolz, um Furcht zu zeigen. Er spricht in Befehlen. Seine Steckbriefe hängen überall in Kargath, und jeder verspricht einen Tribut dem, der sein Urteil vollstreckt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Goretooth führt den längsten Feldzug der {link:horde}Horde{/link} in den Östlichen Königreichen. Seine Streitmacht hat schwer gelitten: Der Dunkeleisengeneral Angerforge metzelte ihre 109. Division nieder. Goretooth hat geschworen, dass Angerforge dafür bezahlen wird.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befehligt die E.K. von {link:kargath}Kargath{/link} aus, mit seinen Offizieren {link:lexlort}Lexlort{/link}, {link:galamav-the-marksman}Galamav{/link}, {link:shadowmage-vivian-lagrave}Vivian Lagrave{/link} und {link:hierophant-theodora-mulvadania}Theodora Mulvadania{/link}.
• Er erlässt Befehle, die Anvilrage-Soldaten von General Angerforge in den {red:blackrock-depths}Blackrocktiefen{/red} zu töten.
• Er plant die Operation, die den Schlächter des {link:blackrock-mountain}Blackrock{/link} seiner gerechten Strafe zuführen soll.
• Er befiehlt den Tod der Herren der {red:blackrock-spire}Blackrockspitze{/red}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Nichts ist über Goretooths Clan oder seine Taten vor der E.K. geschrieben.]=],
		},
	},
	chapters = {
		{
			title = "Sofort töten",
			hint = [=[Folgt den Aushängen des Kriegsherrn gegen die Dunkeleisenzwerge.]=],
			text = [=[Die Aushänge erschienen im Namen des Kriegsherrn an den Mauern von {link:kargath}Kargath{/link}. Angerforges Männer waren skrupellose Mörder, verantwortlich für das Gemetzel an der 109. Division. Jeder Wachmann, Aufseher und Offizier der Anvilrage in den Tiefen sollte vernichtet werden. Goretooth versprach Tribute, und er versprach Angerforge Schlimmeres.]=],
		},
		{
			title = "Tod für Angerforge",
			hint = [=[Vollendet die Operation des Kriegsherrn gegen den Dunkeleisengeneral.]=],
			text = [=[Die letzte Operation war die, auf die der Kriegsherr gewartet hatte. General Angerforge, der Schlächter des {link:blackrock-mountain}Blackrock{/link}, wurde in den Tiefen erschlagen. Goretooth nannte es endlich Gerechtigkeit, und er gab dem, der sie vollstreckt hatte, ein Medaillon der E.K.]=],
		},
		{
			title = "Befehl des Kriegsherrn",
			hint = "Führt den Befehl des Kriegsherrn in der Blackrockspitze aus.",
			text = [=[Goretooth befahl den Tod dreier Herren der Blackrockspitze und verlangte alle Dokumente, die man bei ihren Sachen fände. Die Dokumente kamen zu ihm zurück. Als er sie las, wurde seine grüne Haut für einen Augenblick bleich. Sie besagten, dass Rend Blackhand lebte, ein Häuptling, den man längst für erschlagen hielt. Goretooth sandte Nachricht an {link:eitrigg}Eitrigg{/link} und an {link:thrall}Thrall{/link} in {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[SOFORT TÖTEN: {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}]=],
		},
		{ text = "SOFORT TÖTEN: Hochrangige Dunkeleisenoffiziere" },
		{ text = "Operation: Tod für Angerforge" },
		{ text = "Befehl des Kriegsherrn" },
		{ text = "Eitriggs Weisheit" },
	},
	bonds = {
		{ id = "lexlort", name = "Lexlort", note = "sein Leiter der Aufklärung" },
		{ id = "galamav-the-marksman", name = "Galamav der Scharfschütze", note = "einer seiner Offiziere" },
		{ id = "eitrigg", name = "Eitrigg", note = "kennt die Blackrock am besten" },
		{ id = "thrall", name = "Thrall", note = "sein Kriegshäuptling" },
	},
})

Translate("deDE", "lexlort", {
	title = "Lexlort",
	subtitle = "Großmeister der Aufklärung der E.K.",
	found = "Kargath",
	hint = [=[Sprecht mit dem Meister der Späher der Expeditionsstreitmacht von Kargath.]=],
	allegiance = "Horde · Expeditionsstreitmacht von Kargath",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Großmeister Lexlort leitet die Aufklärung der Expeditionsstreitmacht von {link:kargath}Kargath{/link}. Er war es, der herausfand, wo die hohen Offiziere der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} ihre Soldaten ausbilden. Er verfolgte den Verräter {link:grark-lorkrub}Grark Lorkrub{/link} quer durch {link:searing-gorge}die Sengende Schlucht{/link}, durch den Berg und in die {link:burning-steppes}Brennende Steppe{/link}, wo die {link:blackrock-clan}Orcs der Blackrock{/link} ihm Zuflucht gewährten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Lexlort ist das Auge der E.K. Er führt ihre Spione, darunter eine, der sie nicht ganz trauen kann.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bringt {link:grark-lorkrub}Grark Lorkrub{/link} in Thoriumfesseln zurück, damit er sich für seinen Verrat verantworte.
• Er schickt einen Sucher hinter Bijou her, einer Goblinagentin, die das Geld der E.K. nahm und das eines zweiten Herrn dazu.
• Er erhält Bijous Bericht über die {link:blackrock-clan}Orcs der Blackrock{/link} und gibt zu, dass sie sich wieder einmal herausgewunden hat.]=],
		},
	},
	mentions = {
		{ text = "{link:grark-lorkrub}Grark Lorkrub{/link}" },
		{ text = "Missliche Lage" },
		{ text = "Agentin Bijou" },
		{ text = "Bijous Aufklärungsbericht" },
	},
	bonds = {
		{ id = "warlord-goretooth", name = "Kriegsherr Goretooth", note = "sein Befehlshaber" },
		{ id = "grark-lorkrub", name = "Grark Lorkrub", note = "der Verräter, den er jagte" },
	},
})

Translate("deDE", "galamav-the-marksman", {
	title = "Galamav der Scharfschütze",
	subtitle = "Scharfschütze der E.K.",
	found = "Kargath",
	hint = [=[Sprecht mit dem Scharfschützen der Expeditionsstreitmacht von Kargath.]=],
	allegiance = "Horde · Expeditionsstreitmacht von Kargath",
	aliases = { "Galamav" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Galamav der Scharfschütze ist ein Offizier der E.K., rau von Zunge und scharf von Auge. Er ist nicht sanft mit seinen Soldaten, und er gibt nicht vor, eine Falle sei etwas anderes. Seine Arbeit sind die Worgs der Blackrockspitze und die verlorenen Soldaten der {link:horde}Horde{/link} im Berg.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Als ein Pfeil den Grunzer Gargal oben auf den Kopf traf, fand Galamav eine Notiz, die an den Schaft gebunden war: eine grobe Zeichnung eines {link:orcs}Orcs{/link} hinter Gittern, unterzeichnet von Kommandant Gor'shak. Durch Galamav erfuhr {link:kargath}Kargath{/link}, dass einer seiner Kommandanten noch als Gefangener in den Tiefen lebte.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt Sucher in die {red:blackrock-depths}Blackrocktiefen{/red}, um Kommandant Gor'shak zu finden.
• Er befiehlt den Tod von Halycon, der großen Rudelmutter der Worgs der {link:blackrock-mountain}Blackrock{/link}.]=],
		},
	},
	mentions = {
		{ text = "Kommandant Gor'shak" },
		{ text = "Die Rudelherrin" },
	},
	bonds = {
		{ id = "warlord-goretooth", name = "Kriegsherr Goretooth", note = "sein Befehlshaber" },
		{ id = "commander-gor-shak", name = "Kommandant Gor'shak", note = "ein Gefangener in den Tiefen" },
	},
})

Translate("deDE", "shadowmage-vivian-lagrave", {
	title = "Schattenmagierin Vivian Lagrave",
	subtitle = "Verlassene Gelehrte der E.K.",
	found = "Kargath",
	hint = [=[Sprecht mit der Schattenmagierin der Verlassenen, die die Geheimnisse der Dunkeleisenzwerge erforscht.]=],
	allegiance = [=[Verlassene · Königliche Apothekervereinigung · Expeditionsstreitmacht von Kargath]=],
	aliases = { "Vivian Lagrave" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Vivian Lagrave ist eine Schattenmagierin der {link:forsaken}Verlassenen{/link}, die bei der Expeditionsstreitmacht von {link:kargath}Kargath{/link} dient. Sie findet das {link:badlands}Ödland{/link} reizlos, und sie vermisst die Annehmlichkeiten des Apothecariums. Sie ist aus einem einzigen Grund in Kargath: Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} wissen Dinge, die die {link:royal-apothecary-society}Königliche Apothekervereinigung{/link} wissen will, und sie gedenkt, sie ihnen zu nehmen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Vivian ist die Hand von {link:undercity}Undercity{/link} im Krieg der {link:horde}Horde{/link} gegen die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}. Sie erforscht ihre Gebräue, ihre Alchemie und die Kraft, die ihre Golems antreibt, stets für Zwecke, die den Zielen ihres Volkes entsprechen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie sucht das verlorene Rezept des Donnerbräu-Lagerbiers, das ein Dunkeleisenzwerg stahl, um zu sehen, wie sich seine Stärke gegen die {link:dwarves}Zwerge{/link} der {link:alliance}Allianz{/link} wenden ließe.
• Sie sucht die Dunkelsteintafel, das Werk eines längst toten Alchemisten, in der {red:blackrock-spire}Blackrockspitze{/red}.
• Sie schickt die Essenzen, die die Golems der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} antreiben, nach {link:undercity}Undercity{/link}.]=],
		},
	},
	mentions = {
		{ text = "Vivian Lagrave" },
		{ text = "Das verlorene Donnerbräurezept" },
		{ text = "Vivian Lagrave und die Dunkelsteintafel" },
		{ text = "Die Dunkelsteintafel" },
		{ text = "Das letzte Element" },
	},
	bonds = {
		{ id = "warlord-goretooth", name = "Kriegsherr Goretooth", note = "ihr Befehlshaber" },
	},
})

Translate("deDE", "hierophant-theodora-mulvadania", {
	title = "Hierophantin Theodora Mulvadania",
	subtitle = "Hierophantin der E.K.",
	found = "Kargath",
	hint = [=[Sprecht mit der Hierophantin, die die Maschinen der Dunkeleisenzwerge erforscht.]=],
