	aliases = { "Theodora Mulvadania" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hierophantin Theodora Mulvadania erforscht für die E.K. die Maschinen der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}. Die {link:horde}Horde{/link} begegnete ihnen zuerst in der {link:searing-gorge}Sengenden Schlucht{/link}, und sie verfolgte sie zurück bis in die {link:burning-steppes}Brennende Steppe{/link} und vielleicht bis in die {red:blackrock-depths}Blackrocktiefen{/red}. Sie untersucht ihre Bruchstücke durch ein gewaltiges Monokel.]=],
