		{
			title = "Bedeutung",
			text = [=[Theodora war es, die Initialen fand, eingeätzt in das Fundament der Splitter der Golems, mit einem Rangzeichen darunter. Sie vermutete, dass es das Zeichen eines Erbauers war, und sie schickte sie an {link:lotwil-veriatus}Lotwil Veriatus{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie sammelt Splitter von den Golems und Steinschöpfungen der Brennenden Steppe.
• Sie liest die Buchstaben G.L.A. in den Bruchstücken.
• Sie schickt ihre Probe an {link:lotwil-veriatus}Lotwil Veriatus{/link} in seinem Lager östlich von {link:kargath}Kargath{/link}.]=],
		},
	},
	mentions = {
		{ text = "Der Aufstieg der Maschinen" },
		{ text = "Der Aufstieg der Maschinen" },
	},
	bonds = {
		{ id = "lotwil-veriatus", name = "Lotwil Veriatus", note = "kannte die Zeichen" },
	},
})

Translate("deDE", "thunderheart", {
	title = "Thunderheart",
	subtitle = "Seher der E.K.",
	found = "Kargath",
	hint = "Sprecht mit dem, der in Kargath auf die Elemente lauscht.",
	allegiance = "Horde · Expeditionsstreitmacht von Kargath",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thunderheart lauscht für die Expeditionsstreitmacht von {link:kargath}Kargath{/link} auf die {link:elements}Elemente{/link}. Die Ältesten der {link:horde}Horde{/link} spürten eine Störung unter ihnen, einen Feuergeist, den die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} in die Welt gerufen hatten. Thunderheart schickte Sucher in den Berg, um ihren Ursprung zu finden.]=],
