		{
			title = "Bedeutung",
			text = [=[Thunderheart war der Erste in {link:kargath}Kargath{/link}, der erfuhr, wer wirklich unter dem {link:blackrock-mountain}Blackrock{/link} herrscht.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befiehlt den Tod von {link:overmaster-pyron}Obermeister Pyron{/link} im Steinbruch des {link:blackrock-mountain}Blackrock{/link}.
• Er sucht Lord Incendius in den Tiefen und den Herrn, dem Incendius dient.]=],
		},
	},
	chapters = {
		{
			title = "Die Tafel von Kurniya",
			hint = "Bringt Thunderheart, was man bei Lord Incendius fand.",
			text = [=[Als ihm die Tafel von Kurniya in die Hände gelegt wurde, sprach Thunderheart den Namen aus, den Wind und Erde gerufen hatten: {red:ragnaros}Ragnaros{/red}. Ein General der Alten Götter war in der Welt. Thunderheart sagte {link:kargath}Kargath{/link}, es müsse nun entscheiden, ob es bleiben und kämpfen oder aus Furcht vor einer neuen Teilung fliehen wolle.]=],
		},
	},
	mentions = {
