		{ text = "Disharmonie des Feuers" },
	},
	bonds = {
		{ id = "warlord-goretooth", name = "Kriegsherr Goretooth", note = "sein Befehlshaber" },
		{ id = "galamav-the-marksman", name = "Galamav der Scharfschütze", note = "ein Mitoffizier" },
	},
})

Translate("deDE", "thal-trak-proudtusk", {
	title = "Thal'trak Proudtusk",
	subtitle = "Soldat der E.K.",
	found = "Kargath",
	hint = [=[Sprecht mit dem Soldaten von Kargath, der auf Nachricht von seiner Frau wartet.]=],
	allegiance = "Horde · Expeditionsstreitmacht von Kargath",
	aliases = { "Thal'trak" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thal'trak Proudtusk ist ein Soldat der Expeditionsstreitmacht von {link:kargath}Kargath{/link}. Seine Frau Sha'ni zog mit einem Zug in die {link:burning-steppes}Brennende Steppe{/link}, um zu erfahren, was die Firegut-{link:ogres}Oger{/link} bei ihren Ritualen trieben. Das ist Wochen her. Niemand aus ihrem Zug ist zurückgekehrt, und {link:warlord-goretooth}Kriegsherr Goretooth{/link} hat Thal'trak gesagt, er solle darüber hinwegkommen. Thal'trak kann seinen Posten nicht verlassen, und er kann nicht darüber hinwegkommen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thal'trak erinnert daran, dass der Krieg im Berg von einfachen Soldaten bezahlt wird und von denen, die auf sie warten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt einen Sucher, um zu erfahren, was aus Sha'ni wurde.
• Er bittet um den Nasenring, den sie trug und den der {link:ogres}Oger{/link} {link:krom-grul}Krom'Grul{/link} nahm.]=],
		},
	},
	chapters = {
		{
			title = "Schreckensfels",
			hint = [=[Erfahrt das Schicksal von Thal'traks Frau in der Brennenden Steppe.]=],
			text = [=[Sha'ni würde nicht heimkehren. Sie und Thal'trak hatten geplant, nach dem Ende ihres Dienstes bei ihren Eltern im {link:the-hinterlands}Hinterland{/link} zu leben. Alles, was nach {link:kargath}Kargath{/link} zurückkam, war ihr Nasenring, zurückgeholt von dem {link:ogres}Oger{/link} {link:krom-grul}Krom'Grul{/link} in den Höhlen des {link:dreadmaul-rock}Schreckensfels{/link}.]=],
