})

Translate("deDE", "neeka-bloodscar", {
	title = "Neeka Bloodscar",
	subtitle = "Oberste Späherin von Kargath",
	found = "Kargath",
	hint = "Sprecht mit der obersten Späherin von Kargath.",
	allegiance = "Horde · Kargath",
	aliases = { "Neeka" },
	sections = {
