			title = "Bedeutung",
			text = [=[Neeka hält {link:kargath}Kargath{/link} in Verbindung mit dem Rest der {link:horde}Horde{/link} im Osten. Ihre Berichte sagen, dass die {link:alliance}Allianz{/link} ihre eigenen Sorgen hat und dass einige ihrer Feinde auch die der Horde sein könnten.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie schickt Berichte an {link:helgrum-the-swift}Helgrum{/link} den Schnellen in {link:stonard}Stonard{/link}.
• Sie setzt ein Kopfgeld auf die Felskojoten aus, die Kargaths Nahrung stehlen.]=],
