})

Translate("deDE", "jarkal-mossmeld", {
	title = "Jarkal Mossmeld",
	subtitle = "Alchemist von Kargath",
	found = "Kargath",
	hint = "Sprecht mit dem Trollalchemisten von Kargath.",
	allegiance = "Horde · Kargath",
	aliases = { "Jarkal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Jarkal Mossmeld ist ein Trollalchemist von einigem Ruf, der in {link:kargath}Kargath{/link} arbeitet. Er kauft die Reagenzien des Ödlands und den Pilz von {link:uldaman}Uldaman{/link}, und er braut stärkende Elixiere, auf die er stolz ist. Er hat auch eine Gabe der Sprachen, und er macht es sich zur Aufgabe zu wissen, was Reisende suchen, bevor sie es ihm sagen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Jarkal nennt sich einen Troll, der sein Wort hält, und er hält es, auf seine eigene Weise. Als die Bergungsleute von {link:orgrimmar}Orgrimmar{/link} einen Sucher nach einer zerbrochenen Halskette in {link:uldaman}Uldaman{/link} schickten, übersetzte Jarkal das Tagebuch, das die Hinweise enthielt. Im Gegenzug untersuchte er die Halskette, behielt ihre Kraftquelle und lernte, weitere herzustellen. Die Bergungsleute erfuhren es nie.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sammelt Bussardmägen, Kojotenfänge, Felssplitter und magentafarbene Pilzhüte für seine Arbeit.
• Er zieht das Blut der versengten Wächterdrachen in Gefäße der Thaumaturgie.
• Er übersetzt das Tagebuch eines toten Paladins aus {link:uldaman}Uldaman{/link}.
• Er fertigt Halsketten der Macht, eine für seinen Helfer und mehrere zum Verkauf.]=],
		},
	},
	mentions = {
		{ text = "Reagenzien aus dem {link:badlands}Ödland{/link}" },
		{ text = "Reagenzien aus {link:uldaman}Uldaman{/link}" },
		{ text = "Reagenzien aus dem {link:badlands}Ödland{/link} II" },
		{ text = "Die Übersetzung des Tagebuchs" },
		{ text = "Die Übersetzung des Tagebuchs" },
		{ text = "Findet die Edelsteine und die Kraftquelle" },
		{ text = "Übergabe der Edelsteine" },
		{ text = "Bergung der Halskette, dritter Versuch" },
	},
	bonds = {
		{ id = "dran-droffers", name = "Dran Droffers", note = "der Bergungsmann, den er überlistete" },
	},
})

Translate("deDE", "gorn", {
	title = "Gorn",
	subtitle = "Orc von Kargath",
	found = "Kargath",
	hint = [=[Sprecht mit dem Orc von Kargath, der einen Makel auf der Ehre der Horde tilgen will.]=],
	allegiance = "Horde · Kargath",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gorn ist ein {link:orcs}Orc{/link} von {link:kargath}Kargath{/link}, der sich mit Scham an den {link:second-war}Zweiten Krieg{/link} erinnert. In jenem Krieg stand die {link:horde}Horde{/link} im Bund mit {link:deathwing}Todesschwinge{/link}, und zwei Leutnants des Drachen, {link:blacklash}Blacklash{/link} und {link:hematus}Hematus{/link}, liegen noch immer gebunden unter der Lethlorklamm. Gorn will die verderbten alten Verbündeten der Horde zum Schweigen bringen, um ihre Ehre wiederherzustellen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gorn spricht für den Wunsch der neuen {link:horde}Horde{/link}, die Verbrechen der alten hinter sich zu lassen. Er spricht auch für ihre harten Lehren über die {link:ogres}Oger{/link}, die nicht mehr Teil der Horde sind.]=],
		},
		{
			title = "Taten",
			text = [=[• Er heuerte die {link:ogres}Oger{/link} von {link:boss-tho-grun}Boss Tho'grun{/link} an, um das Zeichen der Erde zu nehmen, und sie verrieten ihn.
• Er schickt die Kämpfer von {link:kargath}Kargath{/link} aus, um das Zeichen zurückzuholen und das Siegel von {link:lethlor-ravine}Lethlor{/link} zu brechen.]=],
		},
	},
	chapters = {
		{
			title = "Zerbrochene Bündnisse",
			hint = [=[Helft dem Orc von Kargath, die Leutnants von Todesschwinge zu töten.]=],
			text = [=[Das Zeichen der Erde kam nach {link:kargath}Kargath{/link} zurück, und die Drachen von {link:lethlor-ravine}Lethlor{/link} wurden nur befreit, um getötet zu werden. Gorn sah darin einen weiteren Schritt. Der schwarze Drachenschwarm stand noch immer an der Seite der abtrünnigen {link:blackrock-clan}Orcs der Blackrock{/link}, und beide mussten gebändigt oder beseitigt werden. Mit den Drachen tot konnte Kargath seinen Blick nach Westen richten, zur {red:blackrock-spire}Blackrockspitze{/red}.]=],
		},
	},
	mentions = {
		{
			text = [=[Zerbrochene Bündnisse, der Verrat von {link:boss-tho-grun}Tho'grun{/link}]=],
		},
		{ text = "Zerbrochene Bündnisse, die Drachen erschlagen" },
		{ text = "Siegel der Erde" },
	},
	bonds = {
		{ id = "boss-tho-grun", name = "Boss Tho'grun", note = "verriet ihn" },
		{ id = "blacklash", name = "Blacklash", note = "ein alter Verbündeter, den er zum Schweigen bringen will" },
		{ id = "hematus", name = "Hematus", note = "ein alter Verbündeter, den er zum Schweigen bringen will" },
	},
})

